@app.route('/')
def index():
    return render_template_string(HTML_TEMPLATE)

@app.route('/create-payment', methods=['POST'])
def create_payment():
    try:
        data = request.get_json()

        payment = paypalrestsdk.Payment({
            "intent": "sale",
            "payer": {
                "payment_method": "paypal"
            },
            "redirect_urls": {
                "return_url": "",
                "cancel_url": ""
            },
            "transactions": [{
                "item_list": {
                    "items": [{
                        "name": "Kis Csomag",
                        "sku": "kiscsomag001",
                        "price": str(data['amount']),
                        "currency": data['currency'],
                        "quantity": 1
                    }]
                },
                "amount": {
                    "total": str(data['amount']),
                    "currency": data['currency']
                },
                "description": "Zsebibaba Kis Csomag vásárlás"
            }]
        })

        if payment.create():
            for link in payment.links:
                if link.rel == "approval_url":
                    return jsonify({"approval_url": link.href})
        else:
            return jsonify({"error": payment.error}), 400

    except Exception as e:
        return jsonify({"error": str(e)}), 500

@app.route('/payment-success')
def payment_success():
    payment_id = request.args.get('paymentId')
    payer_id = request.args.get('PayerID')

    try:
        payment = paypalrestsdk.Payment.find(payment_id)

        if payment.execute({"payer_id": payer_id}):
            return redirect('')
        else:
            return "Hiba történt a fizetés során", 400

    except Exception as e:
        return f"Hiba: {str(e)}", 500

@app.route('/payment-cancel')
def payment_cancel():
    return "Fizetés megszakítva", 200

@app.route('/card-payment', methods=['POST'])
def card_payment():
    try:
        data = request.get_json()

        # Itt implementálható a bankkártyás fizetés logika
        # Például Stripe, Square vagy más fizetési szolgáltató API-jával

        # Példa válasz (valós implementációban itt történne a tényleges fizetés)
        if len(data['cardNumber'].replace(' ', '')) >= 16:
            return jsonify({
                "success": True,
                "transaction_id": "TXN123456789"
            })
        else:
            return jsonify({
                "success": False,
                "error": "Érvénytelen kártyaszám"
            })

    except Exception as e:
        return jsonify({
            "success": False,
            "error": str(e)
        }), 500

if __name__ == '__main__':
    app.run(debug=True, host='0.0.0.0', port=5000)
